import org.powermock.api.mockito.PowerMockito;
import org.powermock.core.classloader.annotations.PrepareForTest;
import org.powermock.modules.junit4.PowerMockRunner;

public class UrlBuilderTest {

    @Mock
    private Connection connection;

    public static final String INPUT_URL = "https://example.com";

    public static void main(String[] args) throws MalformedURLException, URISyntaxException {
        System.out.println(UrlBuilderTest.main(INPUT_URL));
    }

    @BeforeClass
    public static void setup() {
        MockitoAnnotations.initMocks(UrlBuilderTest.class);
        PowerMockito.mockStatic(Connection.class);
        PowerMockito.when(Connection.class, "toString").thenReturn(INPUT_URL);
    }

    @Test
    public void shouldCreateANewUrlBuilderWithTheGivenUrl() throws MalformedURLException, URISyntaxException {
        UrlBuilder urlBuilder = getUrlBuilder();
        assertNotNull(urlBuilder);
        assertEquals(INPUT_URL, urlBuilder.toString());
    }

    @Test
    public void shouldReturnTheCorrectUrlWithoutAnyModifications() throws MalformedURLException, URISyntaxException {
        UrlBuilder urlBuilder = getUrlBuilder();
        URL builtUrl = urlBuilder.build();
        assertEquals(INPUT_URL, builtUrl.toString());
    }

    @Test
    public void shouldAppendKeyValToUrl() throws MalformedURLException, URISyntaxException {
        String key = "key";
        String value = "value";
        UrlBuilder urlBuilder = getUrlBuilder();
        urlBuilder.appendKeyVal(key, value);
        assertEquals(INPUT_URL + "?" + key + "=" + value, urlBuilder.toString());
    }

    @Test
    public void shouldAppendKeyValToUrlWithQuery() throws MalformedURLException, URISyntaxException {
        String key = "key";
        String value = "value";
        UrlBuilder urlBuilder = getUrlBuilder();
        urlBuilder.appendKeyVal(key, value);
        assertEquals(INPUT_URL + "?" + key + "=" + value + "&", urlBuilder.toString());
    }

    @Test
    public void shouldReturnCorrectUrlWithoutQuery() throws MalformedURLException, URISyntaxException {
        String key = "key";
        String value = "value";
        UrlBuilder urlBuilder = getUrlBuilder();
        urlBuilder.appendKeyVal(key, value);
        assertEquals(INPUT_URL + "?" + key + "=" + value, new URL(INPUT_URL).toURI().toString());
    }
}

public class UrlBuilder {

    private StringBuilder sb;

