public class Tests {
    @Test
    public void testUrlBuilder() {
        String inputUrl = "https://www.example.com";
        String key = "key";
        String value = "value";

        UrlBuilder urlBuilder = getUrlBuilder();
        assertNotNull(urlBuilder);

        assertEquals(inputUrl + "?" + key + "=" + value, urlBuilder.toString());

        UrlBuilder urlBuilderWithQuery = getUrlBuilder();
        assertNotNull(urlBuilderWithQuery);
        assertEquals(inputUrl + "?" + key + "=" + value + "&", urlBuilderWithQuery.toString());
    }

    public class UrlBuilder {
        private String inputUrl;

        public UrlBuilder(String inputUrl) {
            this.inputUrl = inputUrl;
        }

        public String toString() {
            return inputUrl;
        }

        public void addParameter(String key, String value) {
            if (inputUrl.contains("?")) {
                inputUrl += "&" + key + "=" + value;
            } else {
                inputUrl += "?" + key + "=" + value;
            }
        }

        public URL buildURL() {
            return new URL(inputUrl);
        }
    }

    private UrlBuilder getUrlBuilder() {
        String inputUrl = "https://www.example.com";
        return new UrlBuilder(inputUrl);
    }
}
